/**
 * @name User input to json.loads
 * @description Taint tracking from function parameters to json.loads
 * @kind path-problem
 * @problem.severity error
 * @id py/taint-to-json-loads
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module JsonLoadsConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = API::moduleImport("json").getMember("loads").getACall().getArg(0)
  }
}

module JsonLoadsFlow = TaintTracking::Global<JsonLoadsConfig>;
import JsonLoadsFlow::PathGraph

from JsonLoadsFlow::PathNode source, JsonLoadsFlow::PathNode sink
where JsonLoadsFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Data flows from parameter $@ to json.loads", source.getNode(), source.getNode().toString()

/**
 * @name JSON loads from parameter
 * @description Check if json.loads parses data from a function parameter
 * @kind problem
 * @problem.severity warning
 * @id py/json-loads-param
 * @tags security
 *       external/cwe/cwe-502
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module JsonParamConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    sink = API::moduleImport("json").getMember("loads").getACall().getArg(0)
  }
}

module JsonParamFlow = TaintTracking::Global<JsonParamConfig>;

from DataFlow::Node source, DataFlow::Node sink
where JsonParamFlow::flow(source, sink)
select sink, "Data flows from parameter $@ to json.loads", source, source.toString()
